import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static Map<String, Integer> all = new HashMap<>();
    static Map<String, Integer> limit = new HashMap<>();
    static int n = 0, m = 0;

    static int searchall(int l, int h) {
        if (l == h) {
            return 1;
        }
        String key = l + "," + h;
        if (all.containsKey(key)) {
            return all.get(key);
        }
        int result = 0;
        result += searchall(l + 1, h);
        result += searchall(l, h - 1);
        for (int i = l + 1; i < h; i++) {
            result += searchall(l, i - 1) * searchall(i + 1, h);
        }
        all.put(key, result);
        return result;
    }

    static int searchlimit(int l, int h, int d) {
        if (l == h) {
            return d < m ? 1 : 0;
        }
        String key = l + "," + h + "," + d;
        if (limit.containsKey(key)) {
            return limit.get(key);
        }
        int result = 0;
        result += searchlimit(l + 1, h, d + 1);
        result += searchlimit(l, h - 1, d + 1);
        for (int i = l + 1; i < h; i++) {
            result += searchlimit(l, i - 1, d + 1) * searchlimit(i + 1, h, d + 1);
        }
        limit.put(key, result);
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        m = scanner.nextInt();
        int res = searchall(1, n) - searchlimit(1, n, 1);
        System.out.println(res);
        scanner.close();
    }
}
